// HasApplicationSessions applies the HasEdge predicate on the "application_sessions" edge.
func HasApplicationSessions() predicate.Submission {
	return predicate.Submission(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, ApplicationSessionsTable, ApplicationSessionsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasApplicationSessionsWith applies the HasEdge predicate on the "application_sessions" edge with a given conditions (other predicates).
func HasApplicationSessionsWith(preds ...predicate.ApplicationSession) predicate.Submission {
	return predicate.Submission(func(s *sql.Selector) {
		step := newApplicationSessionsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasPaymentOrders applies the HasEdge predicate on the "payment_orders" edge.
func HasPaymentOrders() predicate.Submission {
	return predicate.Submission(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, PaymentOrdersTable, PaymentOrdersColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasPaymentOrdersWith applies the HasEdge predicate on the "payment_orders" edge with a given conditions (other predicates).
func HasPaymentOrdersWith(preds ...predicate.PaymentOrder) predicate.Submission {
	return predicate.Submission(func(s *sql.Selector) {
		step := newPaymentOrdersStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasPlacements applies the HasEdge predicate on the "placements" edge.
func HasPlacements() predicate.Submission {
	return predicate.Submission(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, PlacementsTable, PlacementsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasPlacementsWith applies the HasEdge predicate on the "placements" edge with a given conditions (other predicates).
func HasPlacementsWith(preds ...predicate.Placement) predicate.Submission {
	return predicate.Submission(func(s *sql.Selector) {
		step := newPlacementsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Submission) predicate.Submission {
	return predicate.Submission(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Submission) predicate.Submission {
	return predicate.Submission(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Submission) predicate.Submission {
	return predicate.Submission(sql.NotPredicates(p))
}
